// MinimockListObjectsDone returns true if the count of the ListObjects invocations corresponds
// the number of defined expectations
func (m *ObjectServiceMock) MinimockListObjectsDone() bool {
	if m.ListObjectsMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.ListObjectsMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.ListObjectsMock.invocationsDone()
}

// MinimockListObjectsInspect logs each unmet expectation
func (m *ObjectServiceMock) MinimockListObjectsInspect() {
	for _, e := range m.ListObjectsMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to ObjectServiceMock.ListObjects at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterListObjectsCounter := mm_atomic.LoadUint64(&m.afterListObjectsCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.ListObjectsMock.defaultExpectation != nil && afterListObjectsCounter < 1 {
		if m.ListObjectsMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to ObjectServiceMock.ListObjects at\n%s", m.ListObjectsMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to ObjectServiceMock.ListObjects at\n%s with params: %#v", m.ListObjectsMock.defaultExpectation.expectationOrigins.origin, *m.ListObjectsMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcListObjects != nil && afterListObjectsCounter < 1 {
		m.t.Errorf("Expected call to ObjectServiceMock.ListObjects at\n%s", m.funcListObjectsOrigin)
	}

	if !m.ListObjectsMock.invocationsDone() && afterListObjectsCounter > 0 {
		m.t.Errorf("Expected %d calls to ObjectServiceMock.ListObjects at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.ListObjectsMock.expectedInvocations), m.ListObjectsMock.expectedInvocationsOrigin, afterListObjectsCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *ObjectServiceMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockCreateObjectVersionInspect()

			m.MinimockDeleteObjectMetaInspect()

			m.MinimockGetObjectMetaInspect()

			m.MinimockHealthCheckInspect()

			m.MinimockListObjectsInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *ObjectServiceMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *ObjectServiceMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockCreateObjectVersionDone() &&
		m.MinimockDeleteObjectMetaDone() &&
		m.MinimockGetObjectMetaDone() &&
		m.MinimockHealthCheckDone() &&
		m.MinimockListObjectsDone()
}
